 u.capacityMessage='บันทึกไม่ได้ใน fixture: ใช้ช่วงในวันเดียว เริ่มก่อนสิ้นสุด, N จำนวนเต็มบวก และ X จำนวนเต็ม ≥ 0; ข้อจำกัดฟอร์มจำลอง ไม่ใช่ AC ร้าน';return render();
 }
 s.capacity={start,end,limit,waitMinutes};u.capacityMessage='บันทึกช่วง/N/X จำลองแล้ว · X เป็นค่าจำลอง ยังไม่ยืนยันสูตร';render();
}

